<script setup>
import {computed,ref,watch,onMounted,onUnmounted} from 'vue';
import {t as tr,fixed,dateTime,systemMessage} from './i18n.js';
import {isStale} from './statusGlow.js';
const props=defineProps({fleet:Array,data:Object,api:Function,user:Object,active:{type:Boolean,default:true}});
const emit=defineEmits(['select','refresh']);
const chosen=ref(''),pumpId=ref('LL1'),hours=ref(1),report=ref(null),error=ref(''),pending=ref(null),busy=ref(false),clock=ref(Date.now());let timer,serial=0,lastLoad=0,loading=false,loadAgain=false;
const machines=computed(()=>props.fleet||[props.data].filter(Boolean));
const eq=computed(()=>props.data?.equipmentId||chosen.value||machines.value[0]?.equipmentId);
const current=computed(()=>props.data||machines.value.find(x=>x.equipmentId===eq.value));
const locks=computed(()=>current.value?.locks||report.value?.locks||[]);
const lock=computed(()=>locks.value.find(x=>x.id===pumpId.value));
const stale=computed(()=>isStale(current.value,clock.value));
const allowed=computed(()=>props.data&&['Engineer','Leader'].includes(props.user?.role));
const total=computed(()=>Number(report.value?.counts.passed||0)+Number(report.value?.counts.failed||0));
function path(metric){const rows=report.value?.trend||[];return rows.map((p,i)=>`${i?'L':'M'}${i*600/Math.max(1,rows.length-1)},${120-Math.max(0,Math.min(1,metric==='health'?Number(p.health)/100:(Math.log10(Math.max(.001,Number(p[metric])))+3)/7))*110}`).join(' ')}
function status(p){return !p?'phmUnknown':p.fault?'phmFault':p.warning?'phmWarning':'phmHealthy'}
const healthScore=computed(()=>{const value=lock.value?.pump?.health;return stale.value||typeof value!=='number'||!Number.isFinite(value)?null:Math.max(0,Math.min(100,value))});
const gaugeColor=computed(()=>healthScore.value===null?'#a7b9b4':lock.value?.pump?.fault?'#c46c51':lock.value?.pump?.warning?'#d5a44b':'#21977f');
const gaugeNeedle=computed(()=>{const angle=Math.PI*(healthScore.value??0)/100;return {x:130-76*Math.cos(angle),y:120-76*Math.sin(angle)}});
const gaugeLabel=computed(()=>`${tr('phmHealth')}: ${healthScore.value===null?'—':fixed(healthScore.value)} / 100 · ${tr(stale.value?'phmStale':status(lock.value?.pump))}`);
const eventLabel=k=>({'vacuum-service-before':'phmServiceBefore','vacuum-channel-ready':'phmChannelReady','vacuum-started':'phmStarted','vacuum-result':'phmResult','vacuum-warning':'phmWarning','vacuum-serviced':'phmService','vacuum-recovered':'phmRecovered','vacuum-recovery-started':'phmRecoveryStarted'}[k]||'phmMaintenance');
async function load(){if(!eq.value||!props.active||document.hidden)return;if(loading){loadAgain=true;return}loading=true;lastLoad=Date.now();const ticket=++serial;const to=new Date(),from=new Date(to-hours.value*3600000);try{const r=await props.api(`/equipment/${eq.value}/vacuum?pumpId=${pumpId.value}&from=${from.toISOString()}&to=${to.toISOString()}`);if(ticket===serial){report.value=r;error.value=''}}catch(e){if(ticket===serial)error.value=e.message}finally{loading=false;if(loadAgain){loadAgain=false;load()}}}
async function recover(type='vacuum-recover'){busy.value=true;try{if(!pending.value){pending.value={eq:eq.value,body:{commandId:crypto.randomUUID(),type,targetId:pumpId.value,parameters:{cycleId:lock.value.pump.cycle.id,faultGeneration:lock.value.pump.faultGeneration}}};await props.api(`/equipment/${pending.value.eq}/commands`,{method:'POST',body:JSON.stringify(pending.value.body)})}const r=await props.api(`/equipment/${pending.value.eq}/commands/${pending.value.body.commandId}`);if(['succeeded','rejected'].includes(r.status)){error.value=r.status==='rejected'?systemMessage(typeof r.result==='string'?JSON.parse(r.result):r.result):'';pending.value=null;emit('refresh');await load()}}catch(e){error.value=e.message;if(e.status>=400&&e.status<500)pending.value=null}finally{busy.value=false}}
watch([eq,pumpId,hours],()=>{serial++;report.value=null;load()});
watch(()=>props.active,value=>{if(value){clock.value=Date.now();load();if(pending.value&&!busy.value)recover()}});
onMounted(()=>{load();timer=setInterval(()=>{if(!props.active||document.hidden)return;clock.value=Date.now();if(Date.now()-lastLoad>=15000)load();if(pending.value&&!busy.value)recover()},5000)});onUnmounted(()=>{serial++;clearInterval(timer)});
</script>
<template>
<section class="panel phm-panel">
<h2>{{tr('phmTitle')}}</h2><p>{{tr('phmNote')}}</p>
<div v-if="fleet" class="phm-fleet"><article v-for="m in machines" :key="m.equipmentId"><button @click="chosen=m.equipmentId">{{m.equipmentId}}</button><div v-for="n in 3" :key="n" class="phm-mini" @click="chosen=m.equipmentId;pumpId='LL'+n"><b>LL{{n}}</b><span>{{isStale(m,clock)?tr('phmStale'):tr(status(m.locks?.[n-1]?.pump))}}</span><span>{{!isStale(m,clock)?fixed(m.locks?.[n-1]?.pump?.health):'—'}}</span></div><button @click="emit('select',m.equipmentId)">{{tr('phmView')}}</button></article></div>
<div class="phm-controls"><strong>{{eq}}</strong><select v-model="pumpId" aria-label="Load Lock"><option>LL1</option><option>LL2</option><option>LL3</option></select><label>{{tr('phmRange')}} <select v-model="hours"><option :value="1">{{tr('phmHour')}}</option><option :value="24">{{tr('phmDay')}}</option><option :value="720">{{tr('phmMonth')}}</option></select></label></div>
<p v-if="stale" role="status">{{tr('phmStale')}} · {{dateTime(current?.sourceTime)}}</p><p v-if="error" role="alert">{{error}}</p>
<div class="phm-metrics"><article><small>{{tr('phmHealth')}}</small><strong>{{stale?'—':fixed(lock?.pump?.health)}} / 100</strong><span>{{stale?tr('phmStale'):tr(status(lock?.pump))}}</span></article><article><small>{{tr('phmRemaining')}}</small><strong>{{stale?'—':lock?.pump?.remainingCycles??'—'}}</strong></article><article><small>{{tr('phmCycles')}}</small><strong>{{lock?.pump?.lifetimeCycles??'—'}} / {{lock?.pump?.cyclesSinceService??'—'}}</strong></article><article><small>{{tr('phmRate')}}</small><strong>{{total?fixed(report.counts.passed/total*100)+'%':tr('phmNoData')}}</strong><span>{{tr('phmInterrupted')}} {{report?.counts.interrupted||0}}</span></article></div>
<p>{{tr('phmTime')}}: {{lock?.pump?.cycle?.elapsedSeconds??'—'}} · {{tr('phmPressure')}}: {{stale?'—':fixed(lock?.pressure,4)}}</p>
<div class="phm-charts"><figure><figcaption>{{tr('phmPressure')}} · log10</figcaption><template v-if="report?.trend.length"><svg viewBox="0 0 600 130" role="img" :aria-label="tr('phmPressure')"><path :d="path('pressure_max')" fill="none" stroke="#21977f" stroke-width="2"/><path :d="path('pressure_min')" fill="none" stroke="#92baad" stroke-width="1"/></svg><small>{{dateTime(report.trend[0].epoch*1000)}} — {{dateTime(report.trend.at(-1).epoch*1000)}}</small></template><p v-else>{{tr('phmNoData')}}</p></figure>
<figure class="phm-health-gauge"><figcaption>{{tr('phmHealth')}}</figcaption><svg class="health-gauge" viewBox="0 0 260 190" role="img" :aria-label="gaugeLabel" :style="{'--gauge-color':gaugeColor}"><title>{{gaugeLabel}}</title><path d="M35 120 A95 95 0 0 1 225 120" fill="none" stroke="#e0ebe5" stroke-width="14" stroke-linecap="round"/><path v-if="healthScore!==null&&healthScore>0" class="gauge-progress" d="M35 120 A95 95 0 0 1 225 120" pathLength="100" :stroke-dasharray="`${healthScore} 100`" fill="none" :stroke="gaugeColor" stroke-width="14" stroke-linecap="round"/>
<g v-for="value in [0,25,50,75,100]" :key="value" stroke="#90aaa2" stroke-width="1.5"><line :x1="130-107*Math.cos(Math.PI*value/100)" :y1="120-107*Math.sin(Math.PI*value/100)" :x2="130-113*Math.cos(Math.PI*value/100)" :y2="120-113*Math.sin(Math.PI*value/100)"/></g>
<g v-if="healthScore!==null" class="gauge-needle"><line x1="130" y1="120" :x2="gaugeNeedle.x" :y2="gaugeNeedle.y" :stroke="gaugeColor" stroke-width="3" stroke-linecap="round"/><circle cx="130" cy="120" r="6" fill="white" :stroke="gaugeColor" stroke-width="3"/></g><text x="27" y="140" text-anchor="middle" class="gauge-tick">0</text><text x="130" y="10" text-anchor="middle" class="gauge-tick">50</text><text x="234" y="140" text-anchor="middle" class="gauge-tick">100</text><text x="130" y="158" text-anchor="middle" class="gauge-score" :fill="gaugeColor">{{healthScore===null?'—':fixed(healthScore)}}</text><text x="130" y="179" text-anchor="middle" class="gauge-tick">/ 100</text></svg><p class="gauge-status">{{tr(healthScore===null?(stale?'phmStale':'phmUnknown'):status(lock?.pump))}} · {{tr('phmLiveHealth')}}</p></figure></div>
<p>{{tr('phmModel')}}: {{lock?.pump?.modelVersion||'—'}} · {{tr('phmBasis')}}</p>
<button v-if="allowed&&lock?.pump?.fault" :disabled="stale||busy||!!pending" @click="recover()">{{tr('phmRecover')}}</button><button v-if="allowed&&lock?.pump?.fault" :disabled="stale||busy||!!pending||!!lock?.waferId||lock?.pressure<1012||lock?.pump?.recovering" @click="recover('vacuum-service-channel')">{{tr('phmChannel')}}</button><p v-if="lock?.pump?.needsService">{{tr('phmServiceRequired')}}</p><button v-if="pending" :disabled="busy" @click="recover()">{{tr('phmPending')}} · {{tr('phmRefresh')}}</button>
<details><summary>{{tr('phmHistory')}}</summary><article v-for="e in report?.events||[]" :key="e.eventId" class="phm-event"><time>{{dateTime(e.sourceTime)}}</time> · {{tr(eventLabel(e.kind))}} · {{e.payload.pumpId}} <span v-if="e.payload.pump?.cycle">{{tr(e.payload.pump.cycle.status==='passed'?'phmPassed':e.payload.pump.cycle.status==='failed'?'phmFailed':e.payload.pump.cycle.status==='interrupted'?'phmInterrupted':'phmRunning')}} · {{e.payload.pump.cycle.elapsedSeconds}} s</span></article></details>
</section>
</template>
<style scoped>
.phm-panel{min-width:0;margin:20px 0}.phm-panel p,.phm-panel small{font-size:12px;line-height:1.7;color:var(--muted)}.phm-controls{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin:20px 0}.phm-controls select{width:auto}.phm-fleet{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.phm-fleet article,.phm-metrics article{background:var(--surface-alt);border-radius:10px;padding:14px}.phm-fleet button{padding:8px;max-width:100%;font-size:12px}.phm-mini{display:flex;justify-content:space-between;gap:8px;padding:8px 0;font-size:11px;cursor:pointer}.phm-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.phm-metrics article{display:flex;flex-direction:column;gap:8px}.phm-metrics strong{font-size:22px}.phm-metrics span{font-size:11px}.phm-charts{display:grid;grid-template-columns:1fr 1fr;gap:16px}.phm-charts figure{margin:0;min-width:0}.phm-charts svg{width:100%;background:linear-gradient(#e0ebe530 1px,transparent 1px);background-size:100% 30px}.phm-charts .health-gauge{display:block;width:min(100%,300px);margin:8px auto 0;background:none}.gauge-tick{fill:var(--muted);font-size:11px}.gauge-score{font-size:29px;font-weight:700;font-variant-numeric:tabular-nums}.gauge-progress{transition:stroke-dasharray .5s ease,stroke .3s ease}.gauge-needle line{transition:x2 .5s ease,y2 .5s ease}.phm-health-gauge .gauge-status{text-align:center;margin:0 0 10px}@media(prefers-reduced-motion:reduce){.gauge-progress,.gauge-needle line{transition:none}}.phm-event{border-top:1px solid var(--border);padding:10px 0;font-size:12px}.phm-panel details{margin-top:20px}@media(max-width:700px){.phm-metrics{grid-template-columns:1fr 1fr}.phm-charts{grid-template-columns:1fr}.phm-controls{align-items:stretch}.phm-controls strong{width:100%}}
</style>
